// Repro check for "sidebar doesn't reach the bottom of the screen" (components/portal/Shell.tsx).
// Uses a REAL windowed viewport (not fullPage screenshot mode), logs in normally,
// and measures the <aside id="portal-sidebar"> box against the actual viewport/scroll
// geometry at multiple scroll positions on both a short and a long page.
import { chromium } from "playwright";

const BASE = process.argv[2] || "http://localhost:3003";
const EMAIL = process.argv[3];
const PASSWORD = process.argv[4];
const OUT_PREFIX = process.argv[5] || "sidebar";

async function login(page) {
  await page.goto(`${BASE}/login`, { waitUntil: "networkidle" });
  await page.fill("#login-email", EMAIL);
  await page.fill("#login-password", PASSWORD);
  await Promise.all([
    page.waitForLoadState("networkidle"),
    page.click('button:has-text("Sign in")'),
  ]);
}

async function measure(page, label) {
  const info = await page.evaluate(() => {
    const aside = document.querySelector("#portal-sidebar");
    if (!aside) return { found: false };
    const r = aside.getBoundingClientRect();
    const cs = getComputedStyle(aside);
    return {
      found: true,
      asideRect: { top: r.top, bottom: r.bottom, height: r.height },
      position: cs.position,
      innerHeight: window.innerHeight,
      scrollY: window.scrollY,
      docScrollHeight: document.documentElement.scrollHeight,
      bodyHasBanner: document.body.classList.contains("nx-has-banner"),
      nxChrome: getComputedStyle(document.documentElement).getPropertyValue("--nx-chrome"),
      gapBelowAside: window.innerHeight - r.bottom, // >0 means a visible gap under the sidebar
    };
  });
  console.log(`[${label}]`, JSON.stringify(info));
  return info;
}

async function run() {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await login(page);
  await page.waitForTimeout(500);

  // Visit an admin page. Try /admin first (short-ish dashboard), then a page
  // likely to have long content (servers list / a table) to force real scroll.
  const targets = [
    { url: "/admin", label: "admin-home" },
    { url: "/admin/servers", label: "admin-servers" },
    { url: "/admin/customers", label: "admin-customers" },
  ];

  for (const t of targets) {
    const resp = await page.goto(`${BASE}${t.url}`, { waitUntil: "networkidle" }).catch((e) => null);
    if (!resp || resp.status() >= 400) {
      console.log(`[${t.label}] skipped (status ${resp ? resp.status() : "nav-error"})`);
      continue;
    }
    await page.waitForTimeout(300);
    await measure(page, `${t.label}-scrollTop`);
    await page.screenshot({ path: `/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/${OUT_PREFIX}-${t.label}-top.png` });

    // Scroll to the very bottom of the page (real windowed scroll, not fullPage capture).
    const scrolled = await page.evaluate(() => {
      const max = document.documentElement.scrollHeight - window.innerHeight;
      window.scrollTo(0, max);
      return max;
    });
    await page.waitForTimeout(300);
    await measure(page, `${t.label}-scrollBottom(max=${scrolled})`);
    await page.screenshot({ path: `/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/${OUT_PREFIX}-${t.label}-bottom.png` });
  }

  await browser.close();
}

run().catch((e) => {
  console.error(e);
  process.exit(1);
});

