import { chromium } from "playwright";
import fs from "fs";
const BASE = process.argv[2] || "http://localhost:3003";
const URL_PATH = process.argv[3] || "/admin";
const PASSWORD = fs.readFileSync(new URL("./.sandbox-test-pw", import.meta.url), "utf8").trim();

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(60000);
page.setDefaultNavigationTimeout(60000);
await page.goto(`${BASE}/login`, { waitUntil: "networkidle" });
await page.fill("#login-email", "admin@nxeon.local");
await page.fill("#login-password", PASSWORD);
await page.click('button:has-text("Sign in")');
await page.waitForURL(/\/(admin|dashboard)/, { timeout: 60000 });
await page.goto(`${BASE}${URL_PATH}`, { waitUntil: "networkidle" });
await page.waitForTimeout(300);

const info = await page.evaluate(() => {
  const aside = document.querySelector("#portal-sidebar");
  const max = document.documentElement.scrollHeight - window.innerHeight;
  return { max, innerHeight: window.innerHeight, docScrollHeight: document.documentElement.scrollHeight, found: !!aside };
});
console.log("page info:", JSON.stringify(info));

const steps = 10;
for (let i = 0; i <= steps; i++) {
  const y = Math.round((info.max * i) / steps);
  const r = await page.evaluate((y) => {
    window.scrollTo(0, y);
    const aside = document.querySelector("#portal-sidebar");
    const rect = aside.getBoundingClientRect();
    return { scrollY: window.scrollY, top: rect.top, bottom: rect.bottom, gap: window.innerHeight - rect.bottom };
  }, y);
  console.log(`scroll=${r.scrollY} aside.top=${r.top.toFixed(1)} aside.bottom=${r.bottom.toFixed(1)} gapBelow=${r.gap.toFixed(1)}`);
}
